import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Color,
  DoubleSide,
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  ColorNode,
  UVNode,
  MixNode,
} from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @param {Object} config
 * @param {Object} ctx – contains textureLoader, glbLoader, primitives, fontAtlas, etc.
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  /*** ROOT ***/
  const root = new Object3D();
  const pos = config.position ?? [0, 0, 0];
  const rot = config.rotation ?? [0, 0, 0];
  const scl = config.scale ?? [1, 1, 1];
  root.position.set(pos[0], pos[1], pos[2]);
  root.rotation.set(rot[0], rot[1], rot[2]);
  root.scale.set(scl[0], scl[1], scl[2]);

  /*** RAIL ***/
  const railW = 3.6;
  const railH = 0.5;
  const railGeo = new PlaneGeometry(railW, railH);
  const railMat = new MeshStandardNodeMaterial();
  const uv = UVNode();
  const top = new Color('#1b1b23');
  const bottom = new Color('#101015');
  railMat.colorNode = MixNode(
    ColorNode(top),
    ColorNode(bottom),
    uv.y
  );
  railMat.roughness = 0.55;
  railMat.metalness = 0.5;
  railMat.clearcoat = 0.2;
  railMat.side = DoubleSide;
  const railMesh = new Mesh(railGeo, railMat);
  railMesh.position.set(0, 0, 0.15);
  root.add(railMesh);

  /*** CONTACT SHADOW ***/
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
    depthWrite: false,
    side: DoubleSide,
  });
  const shadowMesh = new Mesh(railGeo, shadowMat);
  shadowMesh.position.set(0, -0.06, 0);
  root.add(shadowMesh);

  /*** UNDERLINE BAR ***/
  const underlineW = 0.28;
  const underlineH = 0.025;
  const underlineGeo = new PlaneGeometry(underlineW, underlineH);
  const underlineMat = new MeshStandardNodeMaterial({
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.8,
    side: DoubleSide,
  });
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(0, -0.06, 0.02);
  root.add(underline);

  /*** NAV ENTRIES ***/
  const labels = ['HOME', 'FEATURES', 'COLLECTION', 'PRICING', 'JOURNAL'];
  const spacing = 0.68;
  const entryCount = labels.length;
  const entryGroups = [];
  const timelines = [];

  const activeIdx = 0; // HOME starts active
  const activeColor = new Color('#e8ecf2'); // paper
  const inactiveColor = new Color('#a6adba');
  const hoverColor = new Color('#e8ecf2');

  for (let i = 0; i < entryCount; i++) {
    const cx = (i - (entryCount - 1) / 2) * spacing;
    const grp = new Object3D();
    grp.position.set(cx, 0, 0);
    root.add(grp);

    const isActive = i === activeIdx;
    const txtColor = isActive ? activeColor : inactiveColor;

    // Text mesh via fontAtlas (MSDF)
    const txt = ctx.fontAtlas.createText(labels[i], {
      fontSize: 0.13,
      color: txtColor,
      family: 'JetBrains Mono',
      fontWeight: isActive ? 700 : 400,
    });
    txt.position.set(0, 0, 0.01);
    grp.add(txt);

    // Hit area (transparent)
    const hitGeo = new PlaneGeometry(0.6, 0.34);
    const hitMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0 });
    const hit = new Mesh(hitGeo, hitMat);
    hit.position.set(0, 0, 0);
    grp.add(hit);

    // Store data
    grp.userData = {
      index: i,
      label: labels[i],
      txtMesh: txt,
      isActive,
    };

    // Event handlers (attached to hit mesh)
    const handlers = {};

    handlers.pointerover = () => {
      if (grp.userData.isActive) return;
      const tl = gsap.to(txt.material.color, {
        r: hoverColor.r,
        g: hoverColor.g,
        b: hoverColor.b,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      timelines.push(tl);
    };
    handlers.pointerout = () => {
      if (grp.userData.isActive) return;
      const tl = gsap.to(txt.material.color, {
        r: inactiveColor.r,
        g: inactiveColor.g,
        b: inactiveColor.b,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      timelines.push(tl);
    };
    handlers.pointerdown = () => {
      const tlScale = gsap.to(grp.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      const tlZ = gsap.to(grp.position, {
        z: -0.03,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      timelines.push(tlScale, tlZ);
    };
    handlers.pointerup = () => {
      const tlScale = gsap.to(grp.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      const tlZ = gsap.to(grp.position, {
        z: 0,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      timelines.push(tlScale, tlZ);
    };
    handlers.click = () => {
      if (grp.userData.isActive) return;

      // Deactivate previous
      const prev = entryGroups[activeIdx];
      if (prev) {
        prev.userData.isActive = false;
        gsap.to(prev.txtMesh.material.color, {
          r: inactiveColor.r,
          g: inactiveColor.g,
          b: inactiveColor.b,
          duration: 0.2,
        });
      }

      // Activate new
      grp.userData.isActive = true;
      gsap.to(txt.material.color, {
        r: activeColor.r,
        g: activeColor.g,
        b: activeColor.b,
        duration: 0.2,
      });

      // Move underline
      gsap.to(underline.position, {
        x: cx,
        duration: 0.26,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      });
    };

    hit.userData.handlers = handlers;
    entryGroups.push(grp);
  }

  // Position underline under initial active entry
  underline.position.x = (0 - (entryCount - 1) / 2) * spacing;

  // Rise‑in animation for the whole dock
  gsap.from(root.position, {
    y: root.position.y + 0.4,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });

  /*** CLEANUP ***/
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    railGeo.dispose();
    railMat.dispose();
    shadowMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
    entryGroups.forEach((grp) => {
      grp.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      });
    });
  };

  return root;
}
